package io.github.camtulip.metadata.providers.qq

import kotlin.test.Test
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

class QQMusicQrcDecoderJvmTest {
    @Test
    fun decodeQrcHexInflatesQrcXml() {
        val xml = decodeQqQrcHex(QRC_FIXTURE)

        assertNotNull(xml)
        assertTrue(xml.contains("<QrcInfos>"))
        assertTrue(xml.contains("[0,1000]Run(0,300) away(300,700)"))
    }
}

private const val QRC_FIXTURE =
    ""
